import json

seq = [2, 3, 4, 5, 6, 7, 8, 9, 1]
GRID_SIZE = 23

def generate_grid():
    grid = []
    for r in range(GRID_SIZE):
        row = []
        if r == 0:
            # Row 0: offset 0 for all columns
            for c in range(GRID_SIZE):
                row.append(seq[c % 9])
        elif r <= 10:
            # Rows 1-10: offset 0 for cols 0-8, offset 1 for cols 9-22
            # with diagonal dip at (r,r)
            for c in range(GRID_SIZE):
                if c <= 8:
                    # Offset 0 with diagonal dip
                    if c == r:
                        val = seq[(c - 1) % 9]  # Repeat previous
                    else:
                        val = seq[c % 9]
                else:
                    # Offset 1
                    val = seq[(c + 1) % 9]
                row.append(val)
        else:
            # Rows 11-22: offset 1 for all columns
            for c in range(GRID_SIZE):
                val = seq[(c + 1) % 9]
                row.append(val)
        grid.append(row)
    return grid

